/* =============================================================================


 * SIGNED INTEGER WIDENING CONVERSIONS
 * ============================================================================= */

/**
 * Converts an I8 to I16 (widening conversion).
 *
 * @public
 * @param value - The I8 value to convert (range [-128, 127])
 * @returns The identical numeric value re-branded as I16 (range [-32768, 32767])
 *
 * @remarks
 * Input type: I8 (bigint, range [-128, 127]).
 * Output type: I16 (bigint, range [-32768, 32767]).
 * Direction: widening — every I8 value fits in I16; no range check is performed.
 * Negative values remain negative; the sign is preserved.
 *
 * @example
 * ```typescript
 * const i8Value = assertI8(-100n);
 * const i16Value = convertI8ToI16(i8Value); // -100n as I16
 * ```
 *
 * @see {@link convertI16ToI8} for the inverse narrowing conversion
 */
export function convertI8ToI16(value: I8): I16 {
  assertI8(value);
  assertI16(value);
  return value;
}

