/**
 * Unsigned Integer Conversions
 *
 * Widening (always safe) and narrowing (range-checked) conversions between
 * unsigned branded integer types U8 through U1024.
 *
 * @module common/converters/unsigned-integers
 * @since 2.0.0
 */

import {
  type U8, type U16, type U32, type U64, type U128, type U256, type U512, type U1024,
  U8_MAX, U16_MAX, U32_MAX, U64_MAX, U128_MAX, U256_MAX, U512_MAX,
  assertU8, assertU16, assertU32, assertU64, assertU128, assertU256, assertU512, assertU1024,
} from "../types";

import { ConversionError } from "./errors";

/* =============================================================================
 * UNSIGNED INTEGER WIDENING CONVERSIONS
 *
 * These conversions are always safe because the target type can hold all
 * values of the source type.
 * ============================================================================= */

/**
 * Converts a U8 to U16 (widening conversion).
 *
 * @public
 * @param value - The U8 value to convert (range [0, 255])
 * @returns The identical numeric value re-branded as U16 (range [0, 65535])
 *
 * @remarks
 * Input type: U8 (bigint, range [0, 255]).
 * Output type: U16 (bigint, range [0, 65535]).
 * Direction: widening — all U8 values fit within U16; no range check is performed.
 * - Input assertion: Validates input is a valid U8.
 * - No range check needed (widening is always safe).
 * - Output assertion: Validates result is a valid U16.
 *
 * @example
 * ```typescript
 * const u8Value = assertU8(255n);
 * const u16Value = convertU8ToU16(u8Value); // 255n as U16
 * ```
 *
 * @see {@link convertU16ToU8} for the inverse narrowing conversion
 */
export function convertU8ToU16(value: U8): U16 {
  assertU8(value);
  assertU16(value);
  return value;
}

