/**
 * Converts a U512 to U256 (narrowing conversion).
 *
 * @public
 * @param value - The U512 value to convert (must be in range [0, 2^256 - 1])
 * @returns The value re-branded as U256
 * @throws {ConversionError} If value exceeds U256_MAX (2^256 - 1)
 *
 * @remarks
 * Input type: U512 (bigint, range [0, 2^512 - 1]).
 * Output type: U256 (bigint, range [0, 2^256 - 1]).
 * Direction: narrowing — throws if value does not fit in the target range.
 *
 * @example
 * ```typescript
 * convertU512ToU256(assertU512(2n ** 200n)); // OK
 * convertU512ToU256(assertU512(2n ** 256n)); // Throws ConversionError
 * ```
 *
 * @see {@link convertU256ToU512} for the inverse widening conversion
 */
export function convertU512ToU256(value: U512): U256 {
  assertU512(value);
  if (value > U256_MAX) {
    throw new ConversionError(`Value exceeds U256 maximum`, {
      sourceValue: value,
      sourceType: "U512",
      targetType: "U256",
      reason: `Value must be <= 2^256 - 1`,
    });
  }
  assertU256(value);
  return value;
}

