/* =============================================================================
 * RESCUE TYPE PROMOTIONS (Curve25519FieldElement -> Rc*)
 * ============================================================================= */

/**
 * Promotes a Curve25519FieldElement to an RcPlaintext.
 *
 * @remarks
 * Input type: `Curve25519FieldElement` (bigint, range [0, 2^255 - 20]).
 * Output type: `RcPlaintext` (bigint, same range — a sub-brand of Curve25519FieldElement).
 *
 * This is a **brand promotion** — attaches the `RcPlaintext` brand to indicate
 * the value is plaintext input to the Rescue cipher (Rc) scheme. The Rescue cipher
 * operates over the Curve25519 field, so inputs must be valid Curve25519 elements.
 *
 * The Rescue cipher is used to encrypt confidential token balances in the Umbra protocol.
 *
 * @param value - The Curve25519FieldElement to promote
 * @returns The value as `RcPlaintext`
 *
 * @example
 * ```typescript
 * const fieldElement = assertCurve25519FieldElement(balanceBigInt);
 * const plaintext = convertCurve25519FieldElementToRcPlaintext(fieldElement);
 * ```
 *
 * @see {@link convertRcPlaintextToCurve25519FieldElement} — the inverse extraction
 * @public
 */
export function convertCurve25519FieldElementToRcPlaintext(
  value: Curve25519FieldElement,
): RcPlaintext {
  assertCurve25519FieldElement(value);
  assertRcPlaintext(value);
  return value;
}

/**
 * Promotes a Curve25519FieldElement to an RcCiphertext.
 *
 * @remarks
 * Input type: `Curve25519FieldElement` (bigint, range [0, 2^255 - 20]).
 * Output type: `RcCiphertext` (bigint, same range — a sub-brand of Curve25519FieldElement).
 *
 * This is a **brand promotion** — attaches the `RcCiphertext` brand to indicate
 * the value is a Rescue cipher encrypted output element.
 *
 * @param value - The Curve25519FieldElement to promote
 * @returns The value as `RcCiphertext`
 *
 * @example
 * ```typescript
 * const fieldElement = assertCurve25519FieldElement(encryptedBigInt);
 * const ciphertext = convertCurve25519FieldElementToRcCiphertext(fieldElement);
 * ```
 *
 * @see {@link convertRcCiphertextToCurve25519FieldElement} — the inverse extraction
 * @public
 */
export function convertCurve25519FieldElementToRcCiphertext(
  value: Curve25519FieldElement,
): RcCiphertext {
  assertCurve25519FieldElement(value);
  assertRcCiphertext(value);
  return value;
}

/**
 * Promotes a Curve25519FieldElement to an RcKey.
 *
 * @remarks
 * Input type: `Curve25519FieldElement` (bigint, range [0, 2^255 - 20]).
 * Output type: `RcKey` (bigint, same range — a sub-brand of Curve25519FieldElement).
 *
 * This is a **brand promotion** — attaches the `RcKey` brand to indicate the value
 * is a Rescue cipher key. Keys are derived from X25519 shared secrets and must be
 * valid Curve25519 field elements.
 *
 * @param value - The Curve25519FieldElement to promote
 * @returns The value as `RcKey`
 *
 * @example
 * ```typescript
 * const fieldElement = assertCurve25519FieldElement(derivedKeyBigInt);
 * const key = convertCurve25519FieldElementToRcKey(fieldElement);
 * ```
 *
 * @see {@link convertRcKeyToCurve25519FieldElement} — the inverse extraction
 * @public
 */
export function convertCurve25519FieldElementToRcKey(value: Curve25519FieldElement): RcKey {
  assertCurve25519FieldElement(value);
  assertRcKey(value);
  return value;
}

/**
 * Promotes a Curve25519FieldElement to an RcCounter.
 *
 * @remarks
 * Input type: `Curve25519FieldElement` (bigint, range [0, 2^255 - 20]).
 * Output type: `RcCounter` (bigint, same range — a sub-brand of Curve25519FieldElement).
 *
 * This is a **brand promotion** — attaches the `RcCounter` brand to indicate the
 * value is a Rescue cipher counter. Counters are used in counter-mode encryption
 * to generate unique keystream elements for each plaintext block.
 *
 * @param value - The Curve25519FieldElement to promote
 * @returns The value as `RcCounter`
 *
 * @example
 * ```typescript
 * const fieldElement = assertCurve25519FieldElement(1n);
 * const counter = convertCurve25519FieldElementToRcCounter(fieldElement);
 * ```
 *
 * @see {@link convertRcCounterToCurve25519FieldElement} — the inverse extraction
 * @public
 */
export function convertCurve25519FieldElementToRcCounter(value: Curve25519FieldElement): RcCounter {
  assertCurve25519FieldElement(value);
  assertRcCounter(value);
  return value;
}

