/**
 * Converts a U128 to an RcEncryptionNonce.
 *
 * @remarks
 * Input type: `U128` (bigint, range [0, 2^128 - 1]).
 * Output type: `RcEncryptionNonce` (bigint, same range — a sub-brand of U128).
 *
 * This is a **brand promotion** — attaches the `RcEncryptionNonce` brand to indicate
 * the value is a nonce for Rescue cipher encryption. Unlike the Rescue field element
 * types (which are sub-brands of Curve25519FieldElement), encryption nonces are
 * 128-bit integers that are promoted to the Curve25519 field during cipher setup.
 *
 * Nonces must be unique for each encryption operation with the same key to maintain
 * semantic security. A 128-bit nonce space is sufficient for random generation with
 * negligible collision probability across all practical usage volumes.
 *
 * @param value - The U128 to promote to an RcEncryptionNonce
 * @returns The value as `RcEncryptionNonce`
 *
 * @example
 * ```typescript
 * const nonce = assertU128(crypto.getRandomValues(new Uint8Array(16)));
 * const rcNonce = convertU128ToRcEncryptionNonce(nonce);
 * ```
 *
 * @see {@link convertRcEncryptionNonceToU128} — the inverse extraction
 * @public
 */
export function convertU128ToRcEncryptionNonce(value: U128): RcEncryptionNonce {
  assertU128(value);
  assertRcEncryptionNonce(value);
  return value;
}

