/** Encodes a {@link Bn254FieldElement} to little-endian bytes. @since 2.0.0 @public */
export function encodeBn254FieldElementToLeBytes(value: Bn254FieldElement): U256LeBytes {
  return encodeU256ToU256LeBytes(convertBn254FieldElementToU256(value));
}

/** Encodes a {@link Bn254FieldElement} to big-endian bytes. @since 2.0.0 @public */
export function encodeBn254FieldElementToBeBytes(value: Bn254FieldElement): U256BeBytes {
  return encodeU256ToU256BeBytes(convertBn254FieldElementToU256(value));
}

/** Decodes little-endian bytes to a {@link Bn254FieldElement}. @since 2.0.0 @public */
export function decodeLeBytesToBn254FieldElement(bytes: U256LeBytes): Bn254FieldElement {
  return convertU256ToBn254FieldElement(decodeU256LeBytesToU256(bytes));
}

/** Decodes big-endian bytes to a {@link Bn254FieldElement}. @since 2.0.0 @public */
export function decodeBeBytesToBn254FieldElement(bytes: U256BeBytes): Bn254FieldElement {
  return convertU256ToBn254FieldElement(decodeU256BeBytesToU256(bytes));
}

