/**
 * Token Utilities Module
 *
 * This module provides utilities for working with Solana SPL Token and Token-2022
 * programs, with a focus on the Transfer Fee extension used by some Token-2022 tokens.
 *
 * **Token Programs on Solana:**
 *
 * ```
 * ┌─────────────────────────────────────────────────────────────────────────┐
 * │                      Solana Token Programs                              │
 * ├─────────────────────────────────────────────────────────────────────────┤
 * │                                                                         │
 * │  ┌───────────────────────────┐    ┌───────────────────────────┐         │
 * │  │   SPL Token (Legacy)      │    │   Token-2022              │         │
 * │  ├───────────────────────────┤    ├───────────────────────────┤         │
 * │  │ • Standard fungible       │    │ • All SPL Token features  │         │
 * │  │   tokens                  │    │ • Transfer fees           │         │
 * │  │ • USDC, BONK, etc.        │    │ • Interest-bearing        │         │
 * │  │ • No extensions           │    │ • Confidential transfers  │         │
 * │  │                           │    │ • Transfer hooks          │         │
 * │  │                           │    │ • Non-transferable        │         │
 * │  └───────────────────────────┘    └───────────────────────────┘         │
 * │                                                                         │
 * └─────────────────────────────────────────────────────────────────────────┘
 * ```
 *
 * **Transfer Fee Extension:**
 *
 * Token-2022 tokens can have a transfer fee that is automatically deducted
 * on every transfer. This module provides utilities to:
 * - Extract transfer fee configuration from mint account data
 * - Calculate the fee for a given transfer amount
 * - Handle epoch-based fee schedule transitions
 *
 * **Fee Calculation Formula:**
 *
 * ```
 * fee = ceil((amount × basisPoints) / 10000)
 * actualFee = min(fee, maximumFee)
 * ```
 *
 * Where:
 * - `basisPoints`: Fee percentage × 100 (e.g., 1% = 100 bps)
 * - `maximumFee`: Cap on the fee regardless of amount
 *
 * @example
 * Checking if a token has transfer fees:
 * ```typescript
 * import { extractTransferFeeConfig, calculateTransferFee } from "@umbra-privacy/sdk";
 *
 * // Fetch mint account data
 * const mintAccount = await accountInfoProvider([mintAddress]);
 * const feeConfig = extractTransferFeeConfig(mintAccount.get(mintAddress)?.data);
 *
 * if (feeConfig) {
 *     const epochInfo = await getEpochInfo();
 *     const fee = calculateTransferFee(feeConfig, epochInfo.epoch, amount);
 *     console.log(`Transfer fee: ${fee} tokens`);
 * } else {
 *     console.log("No transfer fee on this token");
 * }
 * ```
 *
 * @packageDocumentation
 * @module common/token
 */

import { address, type Address } from "@solana/kit";

/* =============================================================================
 * TRANSFER FEE EXTENSION TYPES
 * ============================================================================= */

/**
 * Transfer fee schedule configuration.
 *
 * Defines the fee parameters that apply during a specific epoch range.
 * Token-2022 mints can have two fee schedules (older and newer) to allow
 * gradual fee changes without disruption.
 *
 * **Schedule Activation:**
 * - The `olderTransferFee` is active when `currentEpoch < newerTransferFee.epoch`
 * - The `newerTransferFee` becomes active when `currentEpoch >= newerTransferFee.epoch`
 *
 * **Basis Points:**
 * Fees are specified in basis points (bps) where 1 bps = 0.01%.
 *
 * | Basis Points | Percentage |
 * |--------------|------------|
 * | 1 | 0.01% |
 * | 10 | 0.1% |
 * | 100 | 1% |
 * | 1000 | 10% |
 * | 10000 | 100% |
 *
 * @see {@link TransferFeeConfig}
 * @see {@link calculateTransferFee}
 * @public
 */
export interface TransferFeeSchedule {
  /**
   * Solana epoch at which this fee schedule becomes active.
   *
   * @remarks
   * Solana epochs are approximately 2–3 days. When the cluster reaches this epoch number,
   * this schedule's fee parameters replace the older schedule.
   */
  epoch: bigint;

  /**
   * Maximum fee that can be charged per transfer, in token base units.
   *
   * @remarks
   * Caps the fee regardless of transfer amount. For example, if
   * `maximumFee = 1_000_000` and the token has 6 decimals, the cap is 1 token.
   * A value of `BigInt.MAX_VALUE` effectively removes the cap.
   */
  maximumFee: bigint;

  /**
   * Fee in basis points (hundredths of a percent).
   *
   * @remarks
   * A value of 100 bps equals 1%. Valid range is 0–10000 (0%–100%).
   * The fee formula is: `ceil((amount * transferFeeBasisPoints) / 10000)`, capped at `maximumFee`.
   */
  transferFeeBasisPoints: number;
}

/**
 * Transfer Fee Config extension data.
 *
 * Complete transfer fee configuration for a Token-2022 mint.
 * Contains authorities, withheld amounts, and both fee schedules.
 *
 * **Extension Layout:**
 *
 * ```
 * ┌────────────────────────────────────────┐
 * │ Transfer Fee Config (108 bytes)        │
 * ├────────────────────────────────────────┤
 * │ transferFeeConfigAuthority (36 bytes)  │  COption<Pubkey>
 * │ withdrawWithheldAuthority (36 bytes)   │  COption<Pubkey>
 * │ withheldAmount (8 bytes)               │  u64
 * │ olderTransferFee (18 bytes)            │  TransferFeeSchedule
 * │ newerTransferFee (18 bytes)            │  TransferFeeSchedule
 * └────────────────────────────────────────┘
 * ```
 *
 * **Fee Collection:**
 * When transfers occur, fees are "withheld" in the recipient's token account.
 * The `withdrawWithheldAuthority` can collect these fees using the
 * `WithdrawWithheldTokensFromAccounts` instruction.
 *
 * @see {@link TransferFeeSchedule}
 * @see {@link extractTransferFeeConfig}
 * @see {@link calculateTransferFee}
 * @public
 */
export interface TransferFeeConfig {
  /**
   * Authority that can modify the transfer fee configuration.
   *
   * @remarks
   * If `null`, the transfer fee is permanently immutable (no one can change it).
   */
  transferFeeConfigAuthority: Address | null;

  /**
   * Authority that can withdraw fees that have been withheld in token accounts.
   *
   * @remarks
   * If `null`, withheld fees can never be withdrawn and are effectively burned.
   * Use `HarvestWithheldTokensToMint` followed by `WithdrawWithheldTokensFromMint`
   * to collect fees if this authority is set.
   */
  withdrawWithheldAuthority: Address | null;

  /**
   * Total amount of fees currently withheld on the mint account itself (in token base units).
   *
   * @remarks
   * Individual token accounts accumulate fees in their own `withheldAmount` field.
   * Calling `HarvestWithheldTokensToMint` transfers those per-account fees to this
   * mint-level accumulator.
   */
  withheldAmount: bigint;

  /**
   * The older (currently active if epoch has not advanced) transfer fee schedule.
   *
   * @remarks
   * This schedule is active when `currentEpoch < newerTransferFee.epoch`.
   */
  olderTransferFee: TransferFeeSchedule;

  /**
   * The newer (pending or active) transfer fee schedule.
   *
   * @remarks
   * This schedule becomes active when `currentEpoch >= newerTransferFee.epoch`.
   */
  newerTransferFee: TransferFeeSchedule;
}

/* =============================================================================
 * EXTENSION TYPE CONSTANTS
 * ============================================================================= */

/**
 * Extension type discriminator byte value for the Transfer Fee Config extension.
 *
 * @remarks
 * In the Token-2022 extension binary format, each extension block is prefixed with a
 * 2-byte little-endian type discriminator. Value 1 identifies the Transfer Fee Config.
 *
 * @internal
 */
const EXTENSION_TYPE_TRANSFER_FEE_CONFIG = 1;

/**
 * Byte length of the base (non-extended) Token-2022 mint account layout.
 *
 * @remarks
 * The 82 bytes cover: mint authority (COption<Pubkey>, 36 bytes), supply (u64, 8 bytes),
 * decimals (u8, 1 byte), is_initialized (bool, 1 byte), freeze authority (COption<Pubkey>,
 * 36 bytes). Token-2022 mints with extensions will be larger than this.
 *
 * @internal
 */
const MINT_SIZE = 82;

/**
 * Byte offset of the account type discriminator byte in a Token-2022 mint account.
 *
 * @remarks
 * Immediately follows the 82-byte base mint layout. Value 1 means "Mint" (as opposed to
 * "TokenAccount" = 2 or uninitialized = 0).
 *
 * @internal
 */
const ACCOUNT_TYPE_OFFSET = MINT_SIZE;

/**
 * Byte offset where the extension data region begins in a Token-2022 mint account.
 *
 * @remarks
 * Immediately follows the single account-type discriminator byte at `ACCOUNT_TYPE_OFFSET`.
 *
 * @internal
 */
const EXTENSIONS_OFFSET = ACCOUNT_TYPE_OFFSET + 1;

/**
 * Expected byte length of the Transfer Fee Config extension data payload (excluding the
 * 4-byte type+length prefix).
 *
 * @remarks
 * Layout: transferFeeConfigAuthority (36) + withdrawWithheldAuthority (36) +
 * withheldAmount (8) + olderTransferFee (18) + newerTransferFee (18) = 108 bytes.
 *
 * @internal
 */
const TRANSFER_FEE_CONFIG_SIZE = 108;

/* =============================================================================
 * TRANSFER FEE CONFIG EXTRACTION
 * ============================================================================= */

/**
 * Extracts the Transfer Fee Config extension from mint account data.
 *
 * Parses raw mint account bytes to find and decode the Transfer Fee Config
 * extension if present. This function handles the Token-2022 extension
 * serialization format.
 *
 * **Extension Detection Flow:**
 *
 * ```
 * mintData
 *    │
 *    ▼
 * ┌──────────────────────────────────────┐
 * │ 1. Check minimum length (> 83 bytes) │
 * └──────────────────────────────────────┘
 *    │
 *    ▼
 * ┌──────────────────────────────────────┐
 * │ 2. Verify account type = 1 (Mint)    │
 * └──────────────────────────────────────┘
 *    │
 *    ▼
 * ┌──────────────────────────────────────┐
 * │ 3. Iterate through extensions        │
 * │    • Read type (2 bytes)             │
 * │    • Read length (2 bytes)           │
 * │    • Check if type = 1 (TransferFee) │
 * └──────────────────────────────────────┘
 *    │
 *    ▼
 * ┌──────────────────────────────────────┐
 * │ 4. Parse Transfer Fee Config data    │
 * └──────────────────────────────────────┘
 * ```
 *
 * **Return Conditions:**
 * - Returns `null` if mint data is too short for extensions
 * - Returns `null` if account type is not Mint (1)
 * - Returns `null` if Transfer Fee Config extension not found
 * - Returns `null` if extension data is malformed
 * - Returns `TransferFeeConfig` if successfully parsed
 *
 * @param mintData - Raw bytes of the on-chain mint account (`accountInfo.data`)
 * @returns The parsed `TransferFeeConfig` if the extension is present and valid,
 *   or `null` if not found or the data is malformed
 *
 * @example
 * ```typescript
 * import { extractTransferFeeConfig } from "@umbra-privacy/sdk";
 *
 * const mintAccount = await accountInfoProvider([mintAddress]);
 * const mintData = mintAccount.get(mintAddress)?.data;
 *
 * if (mintData) {
 *     const feeConfig = extractTransferFeeConfig(mintData);
 *     if (feeConfig) {
 *         console.log("Token has transfer fees");
 *         console.log(`Fee: ${feeConfig.olderTransferFee.transferFeeBasisPoints} bps`);
 *     }
 * }
 * ```
 *
 * @see {@link TransferFeeConfig}
 * @see {@link calculateTransferFee}
 * @public
 */
export function extractTransferFeeConfig(
  mintData: Uint8Array | undefined,
): TransferFeeConfig | null {
  // Validate input
  if (mintData === undefined || mintData.length === 0) {
    return null;
  }

  // Must be larger than base mint to have extensions
  if (mintData.length <= EXTENSIONS_OFFSET) {
    return null;
  }

  // Check account type byte (should be 1 for Mint)
  const accountType = mintData[ACCOUNT_TYPE_OFFSET];
  if (accountType !== 1) {
    return null;
  }

  // Parse extensions
  let offset = EXTENSIONS_OFFSET;

  while (offset + 4 <= mintData.length) {
    // Read extension type (2 bytes, little endian)
    const extensionType = (mintData[offset] ?? 0) | ((mintData[offset + 1] ?? 0) << 8);
    offset += 2;

    // Read extension length (2 bytes, little endian)
    const extensionLength = (mintData[offset] ?? 0) | ((mintData[offset + 1] ?? 0) << 8);
    offset += 2;

    // Validate extension length is reasonable
    if (extensionLength === 0 || extensionLength > 10_000) {
      // Extension length seems invalid, stop parsing
      break;
    }

    // Check if we have enough data for this extension
    if (offset + extensionLength > mintData.length) {
      break;
    }

    if (extensionType === EXTENSION_TYPE_TRANSFER_FEE_CONFIG) {
      return parseTransferFeeConfig(mintData.slice(offset, offset + extensionLength));
    }

    // Skip to next extension
    offset += extensionLength;
  }

  return null;
}

/**
 * Parses the raw 108-byte Transfer Fee Config extension payload into a typed object.
 *
 * @param data - The extension payload bytes (must be at least `TRANSFER_FEE_CONFIG_SIZE` bytes)
 * @returns The parsed `TransferFeeConfig`, or `null` if the data is too short or contains
 *   invalid values (e.g., basis points > 10000)
 *
 * @privateRemarks
 * This function is called by `extractTransferFeeConfig` once the correct extension has been
 * located in the account data. It does not validate the extension type prefix — that is
 * handled by the caller.
 *
 * @internal
 */
function parseTransferFeeConfig(data: Uint8Array): TransferFeeConfig | null {
  // Validate minimum size
  if (data.length < TRANSFER_FEE_CONFIG_SIZE) {
    return null;
  }

  let offset = 0;

  // Parse transferFeeConfigAuthority (COption<Pubkey>)
  const transferFeeConfigAuthority = parseOptionalPubkey(data, offset);
  offset += 36; // 4 byte discriminator + 32 byte pubkey

  // Parse withdrawWithheldAuthority (COption<Pubkey>)
  const withdrawWithheldAuthority = parseOptionalPubkey(data, offset);
  offset += 36;

  // Parse withheldAmount (u64, little endian)
  const withheldAmount = readU64LE(data, offset);
  offset += 8;

  // Parse olderTransferFee
  const olderTransferFee = parseTransferFeeSchedule(data, offset);
  offset += 18;

  // Parse newerTransferFee
  const newerTransferFee = parseTransferFeeSchedule(data, offset);

  // Validate parsed data
  if (
    olderTransferFee.transferFeeBasisPoints > 10_000 ||
    newerTransferFee.transferFeeBasisPoints > 10_000
  ) {
    // Basis points cannot exceed 100%
    return null;
  }

  return {
    transferFeeConfigAuthority,
    withdrawWithheldAuthority,
    withheldAmount,
    olderTransferFee,
    newerTransferFee,
  };
}

/**
 * Parses a Borsh-encoded `COption<Pubkey>` (36 bytes) at the given offset.
 *
 * @remarks
 * In Borsh serialization, `COption<T>` is encoded as a 4-byte little-endian discriminator
 * (0 = None, 1 = Some) followed by the serialized `T`. For `Pubkey`, `T` is 32 bytes.
 *
 * @param data - The byte buffer containing the serialized data
 * @param offset - Byte offset into `data` where the `COption<Pubkey>` begins
 * @returns The decoded `Address` if the discriminator is 1 (Some), or `null` if 0 (None)
 *
 * @internal
 */
function parseOptionalPubkey(data: Uint8Array, offset: number): Address | null {
  // First 4 bytes are the discriminator: 0 = None, 1 = Some
  const discriminator =
    (data[offset] ?? 0) |
    ((data[offset + 1] ?? 0) << 8) |
    ((data[offset + 2] ?? 0) << 16) |
    ((data[offset + 3] ?? 0) << 24);

  if (discriminator === 0) {
    return null;
  }

  // Extract 32-byte pubkey and convert to Address
  const pubkeyBytes = data.slice(offset + 4, offset + 36);
  return pubkeyBytesToAddress(pubkeyBytes);
}

/**
 * Converts a 32-byte raw public key into a Base58-encoded Solana `Address` string.
 *
 * @remarks
 * Uses the Base58 alphabet used by Bitcoin and Solana (no 0, O, I, l). Leading zero bytes
 * in the input produce leading '1' characters in the output, which matches the Solana
 * address encoding convention.
 *
 * @param bytes - Exactly 32 bytes representing the public key
 * @returns A Base58Check-encoded `Address` string
 *
 * @internal
 */
function pubkeyBytesToAddress(bytes: Uint8Array): Address {
  const ALPHABET = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";

  // Convert bytes to big integer
  let numericValue = 0n;
  for (const byte of bytes) {
    numericValue = numericValue * 256n + BigInt(byte);
  }

  // Convert to base58
  let encoded = "";
  while (numericValue > 0n) {
    const remainder = Number(numericValue % 58n);
    numericValue = numericValue / 58n;
    encoded = (ALPHABET[remainder] ?? "") + encoded;
  }

  // Add leading '1's for leading zeros in the bytes
  for (const byte of bytes) {
    if (byte === 0) {
      encoded = `1${encoded}`;
    } else {
      break;
    }
  }

  return address(encoded);
}

/**
 * Parses a single `TransferFeeSchedule` from binary data at the given offset.
 *
 * @remarks
 * The 18-byte layout is: epoch (u64 LE, 8 bytes) + maximumFee (u64 LE, 8 bytes) +
 * transferFeeBasisPoints (u16 LE, 2 bytes).
 *
 * @param data - The byte buffer containing the serialized schedule
 * @param offset - Byte offset into `data` where the schedule begins
 * @returns The decoded `TransferFeeSchedule`
 *
 * @internal
 */
function parseTransferFeeSchedule(data: Uint8Array, offset: number): TransferFeeSchedule {
  // epoch: u64 (8 bytes, little endian)
  const epoch = readU64LE(data, offset);

  // maximumFee: u64 (8 bytes, little endian)
  const maximumFee = readU64LE(data, offset + 8);

  // transferFeeBasisPoints: u16 (2 bytes, little endian)
  const transferFeeBasisPoints = (data[offset + 16] ?? 0) | ((data[offset + 17] ?? 0) << 8);

  return {
    epoch,
    maximumFee,
    transferFeeBasisPoints,
  };
}

/**
 * Reads a little-endian `u64` (8 bytes) from a byte buffer at the given offset.
 *
 * @remarks
 * Accumulates 8 bytes from most-significant to least-significant using bit-shifts to
 * avoid potential sign-extension issues with 32-bit intermediates.
 *
 * @param data - The byte buffer to read from
 * @param offset - Byte offset into `data` where the u64 begins
 * @returns The decoded `bigint` value in range [0, 2^64 - 1]
 *
 * @internal
 */
function readU64LE(data: Uint8Array, offset: number): bigint {
  let result = 0n;
  for (let index = 7; index >= 0; index--) {
    result = (result << 8n) | BigInt(data[offset + index] ?? 0);
  }
  return result;
}

/* =============================================================================
 * TRANSFER FEE CALCULATION
 * ============================================================================= */

/**
 * Calculates the transfer fee for a given amount based on the fee configuration.
 *
 * Computes the fee that will be deducted from a transfer based on the
 * active fee schedule. The fee is calculated using basis points and
 * capped at the maximum fee.
 *
 * **Fee Calculation:**
 *
 * ```
 * rawFee = ceil((amount × basisPoints) / 10000)
 * actualFee = min(rawFee, maximumFee)
 * ```
 *
 * **Schedule Selection:**
 * - If `currentEpoch >= newerTransferFee.epoch`: Use `newerTransferFee`
 * - Otherwise: Use `olderTransferFee`
 *
 * **Rounding:**
 * The fee is rounded UP (ceiling) to ensure the protocol always collects
 * at least the calculated fee amount.
 *
 * **Examples:**
 *
 * | Amount | Basis Points | Max Fee | Raw Fee | Actual Fee |
 * |--------|--------------|---------|---------|------------|
 * | 1000 | 100 (1%) | 500 | 10 | 10 |
 * | 100000 | 100 (1%) | 500 | 1000 | 500 (capped) |
 * | 50 | 100 (1%) | 500 | 1 | 1 (ceil) |
 * | 1000 | 0 | 0 | 0 | 0 |
 *
 * @param feeConfig - The transfer fee configuration from the mint
 * @param currentEpoch - The current Solana epoch (determines which schedule is active)
 * @param amount - The transfer amount in token base units (before fee)
 * @returns The fee amount in token base units to be withheld
 *
 * @example
 * ```typescript
 * import { extractTransferFeeConfig, calculateTransferFee } from "@umbra-privacy/sdk";
 *
 * const feeConfig = extractTransferFeeConfig(mintData)!;
 * const epochInfo = await getEpochInfo();
 *
 * const transferAmount = 1_000_000n; // 1 token (6 decimals)
 * const fee = calculateTransferFee(feeConfig, epochInfo.epoch, transferAmount);
 *
 * console.log(`Transfer: ${transferAmount}`);
 * console.log(`Fee: ${fee}`);
 * console.log(`Recipient receives: ${transferAmount - fee}`);
 * ```
 *
 * @see {@link extractTransferFeeConfig}
 * @see {@link calculateNetAmountAfterFee}
 * @public
 */
export function calculateTransferFee(
  feeConfig: TransferFeeConfig,
  currentEpoch: bigint,
  amount: bigint,
): bigint {
  // Handle edge cases
  if (amount <= 0n) {
    return 0n;
  }

  // Determine which fee schedule to use based on epoch
  const schedule =
    currentEpoch >= feeConfig.newerTransferFee.epoch
      ? feeConfig.newerTransferFee
      : feeConfig.olderTransferFee;

  // If no fee configured, return 0
  if (schedule.transferFeeBasisPoints === 0) {
    return 0n;
  }

  // Calculate fee: (amount * basisPoints) / 10000, rounded up
  const fee = ceilDiv(amount * BigInt(schedule.transferFeeBasisPoints), 10_000n);

  // Cap at maximum fee (Math.min does not support bigint)
  return fee < schedule.maximumFee ? fee : schedule.maximumFee;
}

/**
 * Performs ceiling (round-up) integer division for `bigint` values.
 *
 * @remarks
 * Equivalent to `Math.ceil(Number(numerator) / Number(denominator))` but exact for arbitrary
 * precision integers. Formula: `(numerator + denominator - 1) / denominator`.
 *
 * @param numerator - The dividend (must be non-negative)
 * @param denominator - The divisor (must be non-zero and positive)
 * @returns `ceil(numerator / denominator)` as a `bigint`
 * @throws {Error} If `denominator` is zero
 *
 * @internal
 */
function ceilDiv(numerator: bigint, denominator: bigint): bigint {
  if (denominator === 0n) {
    throw new Error("Division by zero");
  }
  return (numerator + denominator - 1n) / denominator;
}

/* =============================================================================
 * UTILITY FUNCTIONS
 * ============================================================================= */

/**
 * Calculates the net amount received by the recipient after the transfer fee is withheld.
 *
 * @remarks
 * This is a convenience wrapper around `calculateTransferFee`. The relationship is:
 * ```
 * netAmount = grossAmount - calculateTransferFee(feeConfig, currentEpoch, grossAmount)
 * ```
 *
 * Use this when you know the gross send amount and need to display the effective receive
 * amount. For the inverse (computing a gross amount that results in a specific net receive),
 * a different calculation is needed.
 *
 * @param feeConfig - The transfer fee configuration parsed from the mint account
 * @param currentEpoch - The current Solana epoch (used to select the active fee schedule)
 * @param grossAmount - The amount being transferred in token base units (before fee deduction)
 * @returns The net amount the recipient receives, in token base units
 *
 * @example
 * ```typescript
 * const netAmount = calculateNetAmountAfterFee(feeConfig, currentEpoch, 1_000_000n);
 * console.log(`Sending 1,000,000 tokens, recipient gets ${netAmount}`);
 * ```
 *
 * @see {@link calculateTransferFee}
 * @see {@link extractTransferFeeConfig}
 * @public
 */
export function calculateNetAmountAfterFee(
  feeConfig: TransferFeeConfig,
  currentEpoch: bigint,
  grossAmount: bigint,
): bigint {
  const fee = calculateTransferFee(feeConfig, currentEpoch, grossAmount);
  return grossAmount - fee;
}
