/**
 * Sign Conversions
 *
 * Conversions between signed (I{N}) and unsigned (U{N}) branded integers
 * of the same width. Validates that values are representable in the target sign.
 *
 * @module common/converters/sign-conversions
 * @since 2.0.0
 */

import {
  type U8, type U16, type U32, type U64, type U128, type U256, type U512, type U1024,
  type I8, type I16, type I32, type I64, type I128, type I256, type I512, type I1024,
  U8_MAX, U16_MAX, U32_MAX, U64_MAX, U128_MAX, U256_MAX, U512_MAX,
  I8_MAX, I16_MAX, I32_MAX, I64_MAX, I128_MAX, I256_MAX, I512_MAX, I1024_MAX,
  assertU8, assertU16, assertU32, assertU64, assertU128, assertU256, assertU512, assertU1024,
  assertI8, assertI16, assertI32, assertI64, assertI128, assertI256, assertI512, assertI1024,
} from "../types";

import { ConversionError } from "./errors";
/* =============================================================================

 * SIGNED TO UNSIGNED CONVERSIONS
 *
 * These conversions fail if the signed value is negative.
 * ============================================================================= */

/**
 * Converts an I8 to U8 (sign conversion).
 *
 * @public
 * @param value - The I8 value to convert (must be in range [0, 127])
 * @returns The value re-branded as U8
 * @throws {ConversionError} If value is negative (< 0)
 *
 * @remarks
 * Input type: I8 (bigint, range [-128, 127]).
 * Output type: U8 (bigint, range [0, 255]).
 * Direction: sign conversion — the numeric value is preserved but the type brand changes.
 * Throws if the signed value is negative; non-negative I8 values always fit in U8
 * since I8_MAX (127) <= U8_MAX (255).
 *
 * @example
 * ```typescript
 * convertI8ToU8(assertI8(127n));  // OK: 127n as U8
 * convertI8ToU8(assertI8(-1n));   // Throws ConversionError: cannot convert negative value
 * ```
 *
 * @see {@link convertU8ToI8} for the inverse sign conversion
 */
export function convertI8ToU8(value: I8): U8 {
  assertI8(value);
  if (value < 0n) {
    throw new ConversionError(`Cannot convert negative value ${String(value)} to unsigned type`, {
      sourceValue: value,
      sourceType: "I8",
      targetType: "U8",
      reason: "Value must be non-negative",
    });
  }
  assertU8(value);
  return value;
}

