/* =============================================================================
/* =============================================================================
 * UNSIGNED TO SIGNED CONVERSIONS
 *
 * These conversions fail if the unsigned value exceeds the signed maximum.
 * ============================================================================= */

/**
 * Converts a U8 to I8 (sign conversion).
 *
 * @public
 * @param value - The U8 value to convert (must be in range [0, 127])
 * @returns The value re-branded as I8
 * @throws {ConversionError} If value exceeds I8_MAX (127)
 *
 * @remarks
 * Input type: U8 (bigint, range [0, 255]).
 * Output type: I8 (bigint, range [-128, 127]).
 * Direction: sign conversion — throws if value > I8_MAX because unsigned values
 * in [128, 255] cannot be represented as a non-negative I8.
 *
 * @example
 * ```typescript
 * convertU8ToI8(assertU8(127n)); // OK: 127n as I8
 * convertU8ToI8(assertU8(128n)); // Throws ConversionError: 128 > I8_MAX
 * ```
 *
 * @see {@link convertI8ToU8} for the inverse sign conversion
 */
export function convertU8ToI8(value: U8): I8 {
  assertU8(value);
  if (value > I8_MAX) {
    throw new ConversionError(`Value ${String(value)} exceeds I8 maximum of ${String(I8_MAX)}`, {
      sourceValue: value,
      sourceType: "U8",
      targetType: "I8",
      reason: `Value must be <= ${String(I8_MAX)}`,
    });
  }
  assertI8(value);
  return value;
}

