/**
 * Number ↔ Branded Integer Conversions
 *
 * Provides bidirectional conversions between JavaScript `number` (IEEE 754
 * double-precision, safe integer range ≤ 2^53-1) and the SDK's branded integer
 * types (U8–U1024, I8–I1024).
 *
 * ## Safety
 *
 * - **number → U{N}**: Validates that the input is a non-negative safe integer
 *   within the target type's range.
 * - **U{N} → number**: Validates that the branded bigint value fits within
 *   `Number.MAX_SAFE_INTEGER` (2^53-1). Throws if precision would be lost.
 * - **number → I{N}**: Validates that the input is a safe integer within the
 *   target signed range.
 * - **I{N} → number**: Validates that the branded bigint value fits within
 *   `Number.MIN_SAFE_INTEGER` to `Number.MAX_SAFE_INTEGER`.
 *
 * @module common/converters/number-conversions
 * @since 2.0.0
 */

import {
  type U8, type U16, type U32, type U64, type U128, type U256, type U512, type U1024,
  type I8, type I16, type I32, type I64, type I128, type I256, type I512, type I1024,
  U8_MAX, U16_MAX, U32_MAX, U64_MAX, U128_MAX, U256_MAX,
  I8_MIN, I8_MAX, I16_MIN, I16_MAX, I32_MIN, I32_MAX, I64_MIN, I64_MAX,
  assertU8, assertU16, assertU32, assertU64, assertU128, assertU256, assertU512, assertU1024,
  assertI8, assertI16, assertI32, assertI64, assertI128, assertI256, assertI512, assertI1024,
} from "../types";

import { ConversionError, assertNumberInRange } from "./errors";

const MAX_SAFE = Number.MAX_SAFE_INTEGER;
const MIN_SAFE = Number.MIN_SAFE_INTEGER;
const MAX_SAFE_BIGINT = BigInt(MAX_SAFE);
const MIN_SAFE_BIGINT = BigInt(MIN_SAFE);

/* =============================================================================
 * number → UNSIGNED
 * ============================================================================= */

/**
 * Converts a JavaScript `number` to a {@link U8}.
 *
 * @param value - A non-negative safe integer in range [0, 255].
 * @returns The value branded as {@link U8}.
 * @throws {ConversionError} If not a safe integer or out of range.
 *
 * @since 2.0.0
 * @public
 */
export function convertNumberToU8(value: number): U8 {
  assertNumberInRange(value, 0, Number(U8_MAX), "U8");
  const result = BigInt(value);
  assertU8(result);
  return result;
}

