/* =============================================================================
 * UNSIGNED → number
 * ============================================================================= */

/**
 * Converts a {@link U8} to a JavaScript `number`. Always safe (max 255).
 *
 * @param value - The branded U8 value.
 * @returns The numeric value.
 *
 * @since 2.0.0
 * @public
 */
export function convertU8ToNumber(value: U8): number {
  return Number(value);
}

/**
 * Converts a {@link U16} to a JavaScript `number`. Always safe (max 65535).
 *
 * @param value - The branded U16 value.
 * @returns The numeric value.
 *
 * @since 2.0.0
 * @public
 */
export function convertU16ToNumber(value: U16): number {
  return Number(value);
}

/**
 * Converts a {@link U32} to a JavaScript `number`. Always safe (max ~4.3 billion).
 *
 * @param value - The branded U32 value.
 * @returns The numeric value.
 *
 * @since 2.0.0
 * @public
 */
export function convertU32ToNumber(value: U32): number {
  return Number(value);
}

/**
 * Converts a {@link U64} to a JavaScript `number`.
 *
 * @remarks
 * Throws if the value exceeds `Number.MAX_SAFE_INTEGER` (2^53-1), since
 * JavaScript `number` cannot represent larger integers without precision loss.
 *
 * @param value - The branded U64 value.
 * @returns The numeric value.
 * @throws {ConversionError} If value > `Number.MAX_SAFE_INTEGER`.
 *
 * @since 2.0.0
 * @public
 */
export function convertU64ToNumber(value: U64): number {
  if ((value as bigint) > MAX_SAFE_BIGINT) {
    throw new ConversionError(
      `U64 value ${String(value)} exceeds Number.MAX_SAFE_INTEGER`,
      { sourceValue: value, sourceType: "U64", targetType: "number", reason: "Value exceeds 2^53-1" },
    );
  }
  return Number(value);
}

