/* =============================================================================
 * SIGNED → number
 * ============================================================================= */

/**
 * Converts an {@link I8} to a JavaScript `number`. Always safe (range [-128, 127]).
 *
 * @param value - The branded I8 value.
 * @returns The numeric value.
 *
 * @since 2.0.0
 * @public
 */
export function convertI8ToNumber(value: I8): number {
  return Number(value);
}

/**
 * Converts an {@link I16} to a JavaScript `number`. Always safe (range [-32768, 32767]).
 *
 * @param value - The branded I16 value.
 * @returns The numeric value.
 *
 * @since 2.0.0
 * @public
 */
export function convertI16ToNumber(value: I16): number {
  return Number(value);
}

/**
 * Converts an {@link I32} to a JavaScript `number`. Always safe.
 *
 * @param value - The branded I32 value.
 * @returns The numeric value.
 *
 * @since 2.0.0
 * @public
 */
export function convertI32ToNumber(value: I32): number {
  return Number(value);
}

/**
 * Converts an {@link I64} to a JavaScript `number`.
 *
 * @param value - The branded I64 value.
 * @returns The numeric value.
 * @throws {ConversionError} If value is outside safe integer range.
 *
 * @since 2.0.0
 * @public
 */
export function convertI64ToNumber(value: I64): number {
  const v = value as bigint;
  if (v > MAX_SAFE_BIGINT || v < MIN_SAFE_BIGINT) {
    throw new ConversionError(
      `I64 value ${String(value)} exceeds safe integer range`,
      { sourceValue: value, sourceType: "I64", targetType: "number", reason: "Value outside [-(2^53-1), 2^53-1]" },
    );
  }
  return Number(value);
}

